n43687.content:
\begin{proposition}[Automatic uniformity]\label{auto}
\lean{Expdb.automatic_uniformity_of_choicewise_bounded, Expdb.automatic_uniformity_of_choicewise_infinitesimal}
\leanok
Let $E = E_{{\mathrm{i}}}$ be a non-empty variable set, and let $f = f_{{\mathrm{i}}}: E \to \mathbf{C}$ be a variable function.  \begin{itemize}
    \item[(i)] Suppose that $f(x)=O(1)$ for all (variable) $x \in E$.  Then after passing to a subsequence if necessary, the bound is uniform, that is to say, there exists a fixed $C$ such that $|f(x)| \leq C$ for all $x \in E$.
    \item[(ii)] Suppose that $f(x)=o(1)$ for all (variable) $x \in E$.  Then after passing to a subsequence if necessary, the bound is uniform, that is to say, there exists an infinitesimal $c$ such that $|f(x)| \leq c$ for all $x \in E$.
\end{itemize}
\end{proposition}

n43692.content:
\begin{lemma}[$L^2$ integral estimate]\label{l2-int}
\lean{Expdb.l2_integral_estimate, Expdb.l2_integral_estimate_error}
\leanok
Let $\xi_1,\dots,\xi_R$ be real numbers that are $1/N$-separated.  Then for any interval $I$ of length $T$, and any sequence $a_1,\dots,a_R$ of complex numbers one has
$$ \int_I |\sum_{r=1}^R a_r e(\xi_r t)|^2\ dt = (T + O(N)) \sum_{r=1}^R |a_r|^2.$$
\end{lemma}

n43694.content:
\begin{definition}[Phase function]\label{phase-def}
\lean{Expdb.IsPhaseFunction, Expdb.IsModelPhaseFunction}
\leanok
A \emph{phase function} is a (variable) smooth function $F \colon [1,2] \to \mathbf{R}$.  A phase function $F$ will be called a \emph{model phase function} if there exists a fixed exponent $\sigma > 0$ with the property that
\begin{equation}\label{fpu}
F^{(p+1)}(u) - \frac{d^p}{du^p} u^{-\sigma} = o(1)
\end{equation}
for all (variable) $u \in [1,2]$ and all fixed $p \geq 0$, where $F^{(p+1)}$ denotes the $(p+1)^{\mathrm{st}}$ derivative of $F$.
\end{definition}

n43695.content:
\begin{definition}[Exponent sum growth exponent]\label{beta-def}\uses{phase-def}
\lean{Expdb.exponentSumGrowthExponent, Expdb.IsExponentSumBound}
\leanok
For any fixed $\alpha \geq 0$, let $\beta(\alpha) \in \mathbf{R}$ denote the least possible (fixed) exponent for which the following claim holds: whenever $N, T \geq 1$ are (variable) quantities with $T$ unbounded and $N = T^{\alpha+o(1)}$, $F$ is a model phase function, and $I \subset [N, 2N]$ is an interval, then
$$ \sum_{n \in I} e(T F(n/N)) \ll T^{\beta(\alpha)+o(1)}.$$
\end{definition}

n43696.content:
\begin{lemma}[Non-asymptotic definition of $\beta$]\label{beta-asymp}\uses{beta-def}
\lean{Expdb.exponentSumGrowthExponent_le_iff_nonAsymptotic, Expdb.IsExponentSumBoundNonAsymptotic}
\leanok
Let $\alpha \geq 0$ and $\overline{\beta} \in \mathbf{R}$ be fixed.  Then the following are equivalent:
\begin{itemize}
\item[(i)] $\beta(\alpha) \leq \overline{\beta}$.
\item[(ii)] For every (fixed) $\varepsilon>0$ and $\sigma > 0$ there exists (fixed) $\delta>0$, $P \geq 1$, $C \geq 1$ with the following property: if $T \geq C$, $T^{\alpha-\delta} \leq N \leq T^{\alpha+\delta}$ are (fixed) real numbers, $I \subset [N,2N]$ is a (fixed) interval, and $F$ is a (fixed) phase function such that
\begin{equation}\label{fpu-bound}
     \left|F^{(p+1)}(u) - \frac{d^p}{du^p} u^{-\sigma}\right| \leq \delta
\end{equation}
for all (fixed) $0 \leq p \leq P$ and $u \in [1,2]$, then
$$ |\sum_{n \in I} e(T F(n/N))| \leq C T^{\overline{\beta}+\varepsilon}.$$
\end{itemize}
\end{lemma}

n43698.content:
\begin{lemma}[Trivial bounds on $\beta$]\label{beta-triv}\uses{beta-def}
\lean{Expdb.exponentSumGrowthExponent_eq_sub_one, Expdb.exponentSumGrowthExponent_mem_Icc, Expdb.exponentSumGrowthExponent_zero}
\leanok
For any fixed $\alpha > 1$, we have
    $$ \beta(\alpha) = \alpha-1.$$
    For fixed $0 \leq \alpha \leq 1$, we have
    $$ \frac{\alpha}{2} \leq \beta(\alpha) \leq \alpha.$$
    In particular
    \begin{equation}\label{beta-0}
        \beta(0)=0.
    \end{equation}
    \end{lemma}

n43702.content:
\begin{lemma}[Van der Corput $A$ process for $\beta$]\label{vdca-beta}\uses{beta-def} If $0 \leq \alpha \leq 2/3$ and $h \geq 0$ then
$$ 2\beta(\alpha) \leq \max\left( 2\alpha - h, 2h, \alpha - h + \sup_{2\alpha-1 \leq h' \leq h} \left((h'+1-\alpha)\beta\left(\frac{\alpha}{h'+1-\alpha}\right)+h'\right)\right).$$
\end{lemma}

