n43804.content:
\begin{definition}[Large value pattern]\label{large-pattern-def} A \emph{large value pattern} is a tuple $(N, T, V, (a_n)_{n \in [N,2N]}, J, W)$, where $N > 1$ and $T, V > 0$ are real numbers, $a_n$ is a $1$-bounded sequence on $[N,2N]$, $J$ is an interval of length $T$, and $W$ is a $1$-separated subset of $J$ such that
\begin{equation}\label{V-large}
        \left|\sum_{n \in [N,2N]} a_n n^{-it} \right| \geq V
\end{equation}
for all $t \in W$.

A \emph{Zeta large value pattern} is a large value pattern in which $J = [T,2T]$ and $a_n = 1_I(n)$ for some interval $I \subset [N,2N]$.
\end{definition}

n43805.content:
\begin{definition}[Large value exponent]\label{lv-def}\uses{large-pattern-def} Let $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$ be fixed. We define $\mathrm{LV}(\sigma,\tau)$ to be the least fixed quantity for which the following claim is true: whenever $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ is a large value pattern with $N>1$ unbounded, $T = N^{\tau+o(1)}$, and $V = N^{\sigma+o(1)}$, then
$$ |W| \ll N^{\mathrm{LV}(\sigma,\tau)+o(1)}.$$
\end{definition}

n43806.content:
\begin{lemma}[Asymptotic form of large value exponent]\label{lv-asymp}\uses{lv-def} Let $1/2 \leq \sigma \leq 1$, $\tau \geq 0$, and $\rho \geq 0$ be fixed.  Then the following are equivalent:
    \begin{itemize}
    \item[(i)] $\mathrm{LV}(\sigma,\tau) \leq \rho$.
    \item[(ii)] For every (fixed)  $\varepsilon>0$ there exists $C, \delta>0$ such that if $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ is a large value pattern with $N \geq C$ and $N^{\tau-\delta} \leq T \leq N^{\tau+\delta}$, $N^{\sigma-\delta} \leq V \leq N^{\sigma+\delta}$, then one has
    $$ |W| \leq C N^{\rho+\varepsilon}.$$
    \end{itemize}
\end{lemma}

n43807.content:
\begin{lemma}[Basic properties]\label{lv-basic}\uses{lv-def}
    \begin{itemize}
        \item[(i)] (Monotonicity in $\sigma$) For any $\tau \geq 0$, $\sigma \mapsto \mathrm{LV}(\sigma,\tau)$ is upper semicontinuous and monotone non-increasing.
        \item[(ii)] (Huxley subdivision) For any $1/2 \leq \sigma \leq 1$ and $\tau' \geq \tau$ one has
$$ \mathrm{LV}(\sigma,\tau) \leq \mathrm{LV}(\sigma,\tau') \leq \mathrm{LV}(\sigma,\tau) + \tau'-\tau.$$
In particular, $\tau \mapsto \mathrm{LV}(\sigma,\tau)$ is Lipschitz continuous.
        \item[(iii)]  ($\tau=0$ endpoint) One has $\mathrm{LV}(\sigma,0)=0$ for all $1/2 \leq \sigma \leq 1$, and hence by (ii) $0 \leq \mathrm{LV}(\sigma,\tau) \leq \tau$ for all $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$.
    \end{itemize}
\end{lemma}

n43808.content:
\begin{proof}\uses{auto}
All claims are clear except perhaps for the upper bound
$$ \mathrm{LV}(\sigma,\tau') \leq \mathrm{LV}(\sigma,\tau) + \tau'-\tau,$$
but this follows because any interval of length $N^{\tau'+o(1)}$ may be subdivided into $N^{\tau'-\tau+o(1)}$ intervals of length $N^{\tau+o(1)}$, so on applying Definition \ref{lv-def} to each subinterval and summing (using Lemma \ref{auto} to ensure uniformity), one obtains the claim.
\end{proof}

n43811.content:
\begin{conjecture}[Montgomery conjecture]\label{montgomery-conj}\uses{lv-def}  One has
    \begin{equation}\label{mont-conj}
        \mathrm{LV}(\sigma, \tau) \leq 2 - 2 \sigma
    \end{equation}
     for all fixed $1/2 < \sigma \leq 1$ and $\tau \geq 0$. Equivalently (by Lemma \ref{lv-basic}(ii), (iii) and Lemma \ref{lv-lower}), one has $\mathrm{LV}(\sigma, \tau) = \min(2 - 2 \sigma,\tau)$ for all $1/2 < \sigma \leq 1$ and $\tau \geq 0$.
\end{conjecture}

n43812.content:
\begin{lemma}[Subdivision and the Montgomery conjecture]\label{montgomery-subdivide}\uses{montgomery-conj}  If $\sigma$ is fixed, and the Montgomery conjecture holds for all fixed $\tau < \tau_0$, then
\begin{equation}\label{lvt-opt}
    \mathrm{LV}(\sigma, \tau) \leq \max( 2 - 2 \sigma, \tau - \tau_0 + 2 - 2\sigma)
\end{equation}
for all fixed $\tau \geq 0$.
\end{lemma}

n43814.content:
\begin{lemma}[Raising to a power]\label{power-lemma}\uses{lv-def}  For any $1/2 \leq \sigma \leq 1$, $\tau \geq 0$, and natural number $k$, one has
    $$ \mathrm{LV}(\sigma, k\tau) \leq k \mathrm{LV}(\sigma, \tau).$$
\end{lemma}

n43818.content:
\begin{theorem}[Montgomery large values theorem]\label{montgomery-lv}\uses{beta-def, lv-def} If $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$ is such that
\begin{equation}\label{tab}
\sup_{1 \leq \tau' \leq \tau} \beta(1/\tau') \tau' < 2\sigma - 1
\end{equation}
(this condition is vacuous for $\tau < 1$) then the Montgomery conjecture \eqref{mont-conj} holds for this choice of parameters.
\end{theorem}

n43833.content:
\begin{lemma}[Asymptotic form of large value exponent at zeta]\label{lvz-asymp}\uses{lvz-def} Let $1/2 \leq \sigma \leq 1$, $\tau \geq 0$, and $\rho \geq 0$  be fixed.  Then the following are equivalent:
    \begin{itemize}
        \item[(i)] $\mathrm{LV}_\zeta(\sigma,\tau) \leq \rho$.
        \item[(ii)] For every $\varepsilon>0$ there exists $C,\delta>0$ such that if $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ is a zeta large value pattern with $N > C$, $N^{\tau-\delta} \leq T \leq N^{\tau+\delta}$, and $N^{\sigma-\delta} \leq V \leq N^{\sigma+\delta}$, then one has
              $$ |W| \leq C N^{\rho+\varepsilon}.$$
    \end{itemize}
\end{lemma}

n43834.content:
\begin{lemma}[Basic properties]\label{lvz-basic}\uses{lvz-def}
    \begin{itemize}
        \item[(i)] (Monotonicity in $\sigma$) For any $\tau \geq 0$, $\sigma \mapsto \mathrm{LV}_\zeta(\sigma,\tau)$ is upper semicontinuous and monotone non-increasing.
        \item[(ii)] (Trivial bound) For any $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$, we have $\mathrm{LV}_\zeta(\sigma,\tau) \leq \tau$.
        \item[(iii)] (Domination by large values)  We have $\mathrm{LV}_\zeta(\sigma,\tau) \leq \mathrm{LV}(\sigma,\tau)$ for all $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$.
        \item[(iv)] (Reflection) For $1/2 \leq \sigma \leq 1$ and $\tau > 1$, one has
              $$ \sup_{\sigma \leq \sigma' \leq 1} \mathrm{LV}_\zeta\left(\frac{1}{2} + \frac{1}{\tau-1} (\sigma'-\frac{1}{2}), \frac{\tau}{\tau-1}\right) + \frac{1}{\tau-1} (\sigma'-\sigma) = \frac{1}{\tau-1} \sup_{\sigma \leq \sigma' \leq 1} (\mathrm{LV}_\zeta(\sigma',\tau) + \sigma'-\sigma).$$
    \end{itemize}
\end{lemma}

n43836.content:
\begin{lemma}[Characterization of negative infinite value]\label{lvz-infty}\uses{lvz-def}  Let $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$ be fixed. Then the following are equivalent:
    \begin{itemize}
        \item[(i)] $\mathrm{LV}_\zeta(\sigma,\tau)=-\infty$.
        \item[(ii)] $\mathrm{LV}_\zeta(\sigma,\tau) < 0$.
        \item[(iii)] There exists a fixed $\varepsilon>0$ such that if $N$ is unbounded and $I$ is a subinterval of $[N, 2N]$, then one has
              $$ \sum_{n \in I} n^{-it} \ll N^{\sigma-\varepsilon+o(1)}$$
              whenever $|t| = N^{\tau+o(1)}$.
    \end{itemize}
\end{lemma}

n43850.content:
\begin{lemma}[From exponent pairs to zeta large values estimate]\label{zeta-from-exp}\uses{lvz-def, exp-pair-def}\cite[Theorem 8.2]{ivic} If $(k,\ell)$ is an exponent pair with $k>0$, then for any $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$ one has
    $$ \mathrm{LV}_\zeta(\sigma,\tau) \leq \max\left( \tau - 6(\sigma-1/2), \frac{k+\ell}{k} \tau - \frac{2(1+2k+2\ell)}{k} (\sigma-1/2) \right).$$
\end{lemma}

n43851.content:
\begin{lemma}[Hal\'asz--Montgomery inequality]\label{hl-improv}\uses{lv-def, lvz-def}  For any $1/2 \leq \sigma \leq 1$ and $\tau \geq 0$, we have
    $$ \mathrm{LV}(\sigma,\tau) \leq \max\left(2-2\sigma, 1 - 2\sigma + \sup_{\stackrel{1 \leq \tau' \leq \tau}{\max(1/2,2\sigma-1) \leq \sigma' \leq 1}}  \sigma' + \mathrm{LV}_\zeta(\sigma',\tau') \right).$$
\end{lemma}

n43867.content:
\begin{lemma}\label{mad}\uses{zeta-moment-def, lvz-def}  If $1/2 \leq \sigma_0 \leq 1$ and $A \geq 1$, then
\begin{equation}\label{M-form}
 M(\sigma_0,A) = \sup_{\tau \geq 2; \sigma \geq 1/2} (A(\sigma-\sigma_0) + \mathrm{LV}_\zeta(\sigma,\tau))/\tau.
\end{equation}
In particular, one has
$$ \mathrm{LV}_\zeta(\sigma,\tau) \leq \tau M(\sigma_0,A) - A(\sigma-\sigma_0)$$
whenever $\sigma \geq 1/2$ and $\tau \geq 2$.
\end{lemma}

n43873.content:
\begin{theorem}[Auxiliary Heath-Brown estimate]\label{hb-12-aux}\uses{lvz-def}  For $\tau \geq 2$ and $1/2 \leq \sigma \leq 1$, one has
$$ \mathrm{LV}_\zeta(\sigma,\tau) \leq \min( \tau-6(\sigma-1/2), 5\tau-32(\sigma-1/2)).$$
\end{theorem}

n43879.content:
\begin{lemma}[Mixed moments and large values of zeta]\label{mad-variant}\uses{mixed-moment-def, lvz-def}  If $1/2 \leq \sigma_0 \leq 1$, $A \geq 1$, and $h \geq 0$ are fixed, then
    \begin{equation}\label{msah}
        M(\sigma_0,A,\geq h) \leq \sup_{\tau \geq 2; \sigma \geq 1/2, h\tau} (A(\sigma-\sigma_0) + \mathrm{LV}_\zeta(\sigma,\tau))/\tau.
    \end{equation}
and
\begin{equation}\label{msah-2}
    M(\sigma_0,A,\leq h) \leq \sup_{\tau \geq 2; \sigma \leq 1/2, h\tau} (A(\sigma-\sigma_0) + \mathrm{LV}_\zeta(\sigma,\tau))/\tau.
\end{equation}
That is to say, any bound of the form
$$ \mathrm{LV}_\zeta(\sigma,\tau) \leq M \tau - A (\sigma - \sigma_0)$$
whenever $\tau \geq 2$ and $\sigma \geq 1/2, h\tau$, gives rise to a bound
$$ M(\sigma_0,A,\geq h) \leq M.$$
Similarly for $M(\sigma_0,A,\geq h)$, in which we replace the condition $\sigma \geq h\tau$ by $\sigma \leq h\tau$.
\end{lemma}

n43886.content:
\begin{lemma}[Zero density theorems from mixed moment bounds]\label{bourgain-remark-2}\cite[Proposition 5]{bourgain_remarks_1995}\uses{lv-def, zeta-grow-def, mixed-moment-def}  Suppose that $M(1/2,6,\geq h) \leq 1$ for some $h \geq 0$.  Then for any $1/2 \leq \alpha < \sigma < 1$, one has
$$ \mathrm{A}(\sigma) \leq \max\left( \frac{4\mu(\alpha)}{\sigma-\alpha}, \frac{3}{8\sigma-5}, \frac{6h}{4\sigma-3}\right).$$
\end{lemma}

n43891.content:
\begin{lemma}[Cauchy--Schwarz and double $\zeta$-sums]\label{cauchy-schwarz}\uses{energy-def} \cite[Lemma 3.4]{bourgain_dirichlet_2000} If $W,W'$ are finite sets of reals, $N>1$, and $a_n$ is a $1$-bounded sequence for $n \in [N,2N]$, then
\begin{equation}\label{ttww}
     \sum_{t \in W, t' \in W'} \left|\sum_{n \in [N,2N]} a_n n^{-it} \right|^2 \leq S(N,W)^{1/2} S(N,W')^{1/2}.
\end{equation}
In particular
$$ \sum_{t \in W} \left|\sum_{n \in [N,2N]} a_n n^{-it} \right|^2 \leq S(N,W).$$
\end{lemma}

n43893.content:
\begin{lemma}[Energy controlled by third moment]\label{energy-third}\uses{energy-def} Suppose that $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ is a large value pattern with $T \geq 1$ and $1 \leq N \ll T^{O(1)}$.  Then
$$ V^2 E_1(W) \ll T^{o(1)} \sum_{n,m \in [N,2N]} |R_W(n/m)|^3 + T^{-50}.$$
\end{lemma}

n43895.content:
\begin{lemma}\label{wtu}\uses{energy-def} If $W \subset [-T,T]$ is $1$-separated and $1 \leq N \ll T^{O(1)}$, then one has
$$ S_4(N,W) \ll T^{o(1)} u^2 S(N,U) + T^{-100}$$
for some $1 \leq u \ll |W|$ and $1$-separated subset $U$ of $[-2T,2T]$ with
\begin{equation}\label{v1}
 u |U| \ll |W|^2
\end{equation}
and
\begin{equation}\label{v2}
     u^2 |U| \ll E_1(W).
\end{equation}
\end{lemma}

n43897.content:
\begin{definition}[Large value energy region]\label{lv-edef} The \emph{large value energy region} $\mathcal{E}\subset \mathbf{R}^5$ is defined to be the set of all fixed tuples $(\sigma,\tau,\rho,\rho^*,s)$ with $1/2 \leq \sigma \leq 1$, $\tau, \rho, \rho' \geq 0$, such that there exists a large value pattern $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ with $N>1$ unbounded, $V = N^{\sigma+o(1)}$, $T = N^{\tau+o(1)}$, $V = N^{\sigma+o(1)}$, $|W| = N^{\rho+o(1)}$, $E_1(W) = N^{\rho^*+o(1)}$ and $S(N,W) = N^{s+o(1)}$.

We define the \emph{zeta large value energy region} $\mathcal{E}_\zeta \subset \mathbf{R}^5$ similarly, but where now $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ is required to be a zeta large value pattern.
\end{definition}

n43902.content:
\begin{lemma}[Non-asymptotic form of large value energy region]\label{lve-asymp}\uses{lv-edef} Let $1/2 \leq \sigma \leq 1$, $\tau \geq 0$,  $\rho, \rho^* \geq 0$, and $s \in \mathbf{R}$ be fixed.  Then the following are equivalent:
    \begin{itemize}
    \item[(i)] $(\sigma,\tau,\rho,\rho^*,s) \in \mathcal{E}$.
    \item[(ii)] For every $\varepsilon>0$ there exists $C, \delta > 0$ such that there is a large value pattern $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ with $N \geq C$, $N^{\tau-\delta} \leq T \leq N^{\tau+\delta}$, $N^{\sigma-\delta} \leq V \leq N^{\sigma+\delta}$,
    $N^{\rho-\varepsilon} \leq |W| \leq N^{\rho+\varepsilon}$,
    $N^{\rho^*-\varepsilon} \leq E_1(W) \leq N^{\rho^*+\varepsilon}$, and
    $N^{s-\varepsilon} \leq S(N, W) \leq N^{s+\varepsilon}$.
    \end{itemize}
    Similarly with $\mathcal{E}$ replaced by $\mathcal{E}_\zeta$, and with $(N,T,V,(a_n)_{n \in [N,2N]},J,W)$ required to be a zeta large value pattern.
\end{lemma}

n43907.content:
\begin{lemma}[Monotonicity criterion]\label{lver_e_mono_crit}
Let $\mathcal{E}_1$ be the intersection of sets $E_i$, each of the form
\begin{align*}
\{(\sigma, \tau, \rho, \rho^*, s) \in \mathbf{R}^5: \rho \le f_1(\rho^*, s), \rho^* \le f_2(\rho, s), s \le f_3(\rho, \rho^*)\}
\end{align*}
for some monotonically increasing functions $f_1, f_2, f_3$ (that possibly also depend on $\sigma$ and $\tau$).

Suppose amongst all tuples $(\sigma, \tau, \rho', (\rho^*)', s') \in \mathcal{E}_1$ with $\rho' \le \rho$, $(\rho^*)' \le \rho^*$ and $s' \le s$, there exists a tuple with $\rho' = \rho$, a tuple with $(\rho^*)' = \rho^*$ and a tuple with $s' = s$ (not necessarily the same tuple each time). Then, $(\sigma, \tau, \rho, \rho^*, s) \in \mathcal{E}_1$.
\end{lemma}

n43910.content:
\begin{proof}
Suppose that $(\sigma, \tau, \rho, \rho^*, s) \in \mathcal{E}\subseteq \mathcal{E}_1$. By Lemma \ref{power-energy} and Lemma \ref{lver_e_mono_crit}, $(\sigma, \tau/k, \rho/k, \rho^*/k, s/k) \in \mathcal{E}_1$, hence by definition $(\sigma, \tau, \rho, \rho^*, s) \in \mathcal{E}_k$.
\end{proof}

n43911.content:
\begin{theorem}[Reflection principle]\label{reflect}\cite[\S 11.5]{ivic}\uses{lv-edef} If $(\sigma,\tau,\rho,\rho^*,s) \in \mathcal{E}$ with $\sigma \geq 3/4$ and $\tau>1$, then for any integer $k \geq 1$, either $\rho \leq 2-2\sigma$, or there exists $0 < \alpha \leq k(\tau-1)$ and $(\sigma, \tau/\alpha, \rho/\alpha, \rho^*/\alpha, s'/\alpha) \in \mathcal{E}$ such that
$$ \rho \leq \min( 2-2\sigma, k(3-4\sigma)/2 + s' - 1).$$
\end{theorem}

n43915.content:
\begin{lemma}\label{double-zeta-from-exp-pair}\cite[Lemma 11.2]{ivic}\uses{lv-edef}  If $(k,\ell)$ is an exponent pair with $k>0$, and $(\sigma,\tau,\rho,\rho^*,s) \in \mathcal{E}$, then
$$ s \leq \max\left( \rho+1, 5\rho/3 + \tau/3, \frac{2+3k+4\ell}{1+2k+2\ell} \rho + \frac{k+\ell}{1+2k+2\ell} \tau\right) + 1.$$
\end{lemma}

n43917.content:
\begin{lemma}[Heath-Brown bound on double sums]\label{hb-double}\uses{lv-edef}  If $(\sigma,\tau,\rho,\rho^*,s) \in \mathcal{E}$, then
    $$ s \leq \max( \rho+1, 2\rho, 5\rho/4+\tau/2) + 1.$$
\end{lemma}

n43925.content:
\begin{theorem}
If $(k, \ell)$ be an exponent pair with $k > 0$ and $(\sigma, \tau, \rho, \rho^*, s)\in \mathcal{E}$, then
\begin{align*}
\rho^* \le 1 - 2\sigma &+ \frac{1}{2}\max\left(\rho+1, \frac{5}{3}\rho + \frac{\tau}{3}, \frac{2+3k+4\ell}{1+2k+2\ell} \rho + \frac{k+\ell}{1+2k+2\ell} \tau\right)\\
&+ \frac{1}{2}\max\left(\rho^*+1, 4\rho, \frac{3}{4}\rho^*+\rho+\frac{\tau}{2}\right).
\end{align*}
\end{theorem}

n43926.content:
\begin{proof}\uses{wtu-alt}
By Lemma \ref{wtu-alt} and Lemma \ref{double-zeta-from-exp-pair}, there exists some $(\sigma, \tau, \rho', (\rho^*)', s') \in \mathcal{E}$ satisfying
\begin{equation}\label{kappa-bounds}
0 \le \kappa \le \rho,\qquad \kappa + \rho' \le 2\rho,\qquad 2\kappa + \rho' \le \rho^*
\end{equation}
and
\begin{align*}
\rho^* + 2\sigma \le \kappa &+ \frac{1}{2}\max\left( \rho+1, 5\rho/3 + \tau/3, \frac{2+3k+4\ell}{1+2k+2\ell} \rho + \frac{k+\ell}{1+2k+2\ell} \tau\right)\\
&+ \frac{1}{2}\max\left(\rho' + 1, 2\rho', \frac{5}{4}\rho' + \frac{\tau}{2}\right) + 1.
\end{align*}
The result follows by moving the $\kappa$ term into the second maximum and applying \eqref{kappa-bounds}.
\end{proof}

n43933.content:
\begin{lemma}[Third Guth-Maynard relation]\label{gm-3}\uses{lv-edef}  If $(\sigma,\tau,\rho,\rho^*, s) \in \mathcal{E}$ and $1 \leq \tau \leq 4/3$, then
    $$ \rho^* \leq \max(\rho+4-4\sigma, 21\rho/8+\tau/4+1-2\sigma, 3\rho+1-2\sigma).$$
\end{lemma}

n43937.content:
\begin{theorem}[Additional Guth--Maynard large values estimate]\label{guth-maynard-extra} For any $1/2 < \sigma < 1$, $\tau \geq 1$, and natural number $k$ one has
    \begin{equation}\label{general-tau}
    \begin{split}
        \mathrm{LV}(\sigma,\tau) \leq \max\Big(&2-2\sigma, 5-6\sigma, (4-6\sigma)\frac{k}{k+1} + \frac{k}{k+1} \tau, (5-6\sigma) \frac{4k}{4k+3} + \frac{2}{4k+3} \tau, \\
        &2-4\sigma + \frac{4}{3} \tau, 3-4\sigma+ \frac{\tau}{2}, \frac{9}{2}-7\sigma+\tau, \frac{72-112\sigma}{19} + \frac{18}{19} \tau\Big).
    \end{split}
    \end{equation}
If one specializes to the case $\sigma \geq 7/10$ and $1 \leq \tau \leq 6/5$, one then has
    \begin{equation}\label{second-bound} \mathrm{LV}(\sigma,\tau) \leq \max\Big(2-2\sigma, 3-4\sigma+\frac{\tau}{2}, (4-6\sigma)\frac{k}{k+1} + \frac{k}{k+1} \tau, (5-6\sigma) \frac{4k}{4k+3} + \frac{2}{4k+3} \tau\Big).
    \end{equation}
and also
\begin{equation}\label{third-bound}
     \mathrm{LV}(\sigma,\tau) \leq \max\Big(2-2\sigma, 3-4\sigma+\frac{\tau}{2}, \frac{46-60\sigma}{5} + \frac{30\sigma-21}{5} \tau\Big).
\end{equation}
\end{theorem}

n43938.content:
\begin{proof}
(Sketch) The first bound \eqref{general-tau} is \cite[(12.1)]{guth-maynard}, and is proven by the same methods used to prove Theorem \ref{guth-maynard-lvt}.  The second and third bounds \eqref{second-bound}, \eqref{third-bound} are in \cite[Proposition 12.1]{guth-maynard}.  The second bound \eqref{second-bound} follows from the $k=3$ case of Theorem \ref{jutila-lvt} when $\sigma \geq 39/50$, and from \eqref{general-tau} together with Theorems \ref{l2-mvt}, \ref{huxley-lv} for $\sigma < 39/50$.  The third bound \eqref{third-bound} follows from Theorems \ref{l2-mvt}, \ref{huxley-lv} when $\tau \leq 4-4\sigma$, and for $\tau > 4-4\sigma$
the bound follows from \eqref{second-bound} after optimizing in $k$ (see the proof of \cite[Proposition 12.1]{guth-maynard} for details).
\end{proof}

n43939.content:
\begin{theorem}[Bourgain large values theorem]\label{bourgain-lvt}\uses{lv-def} \cite{bourgain_large_2000} Let $1/2 < \sigma < 1$ and $\tau > 0$, and let $\rho := \mathrm{LV}(\sigma,\tau)$.  Let $\alpha_1, \alpha_2 \geq 0$ be real numbers.  Then either
    \begin{equation}\label{rho1}
     \rho \leq \max( \alpha_2 + 2 - 2 \sigma, -\alpha_2 + 2\tau+4-8\sigma, -2\alpha_1 + \tau + 12 - 16 \sigma)
    \end{equation}
    or else there exists $s \geq 0$ such that
    \begin{equation}\label{rs}
    \begin{split}
         &\frac{1}{2}\max(\rho+2, 2\rho+1, 5\rho/4 + \tau/2 + 1) + \frac{1}{2}\max(s+2, 2s+1, 5s/4 + \tau/2 + 1) \geq \\
            &\qquad\max( -2\alpha_1 + 2\sigma + s + \rho, -\alpha_1 - \alpha_2/2 + 2\sigma + s/2 + 3\rho/2).
    \end{split}
    \end{equation}
    \end{theorem}

n43940.content:
\begin{proof}  By Definition \ref{lv-def}, we can find a large value pattern $(N,T,V,(a_n)_{n \in [N,2N]},J,R)$ with $N>1$ unbounded, $N \geq 1$, $T = N^{\tau+o(1)}$, $|R| = N^{\rho+o(1)}$, $V = N^{\sigma+o(1)}$; we use $R$ here instead of $W$ to be consistent with the notation from \cite{bourgain_large_2000}.  Now set $\delta_1 := N^{-\alpha_1}$, $\delta_2 := N^{-\alpha_2}$.  From \cite[(4.41), (4.42)]{bourgain_large_2000}, one has the inequality
        $$ |R| \leq |R^{(1)}| + |R^{(2)}|$$
        for certain sets $R^{(1)}$ and $R^{(2)}$ with the former set obeying the bound
    $$ |R^{(1)}| \ll \delta_2^{-1} N^2 V^{-2} + \delta_2 T^2 N^4 V^{-8} + \delta_1^2 T N^{12} V^{-16}.$$
    Hence, we either have
    $$ |R| \ll \delta_2^{-1} N^2 V^{-2} + \delta_2 T^2 N^4 V^{-8} + \delta_1^2 T N^{12} V^{-16}$$
    which implies \eqref{rho1}, or else
    \begin{equation}\label{rr}
        |R| \ll |R^{(2)}|.
    \end{equation}
    Henceforth we assume that \eqref{rr} holds. From \cite[(4.53), (4.54)]{bourgain_large_2000} we may upper bound
    \begin{equation}\label{Exp-1}
         T^{-\varepsilon} \delta' (\delta'')^2 V^2 |S| |R^{(2)}| + T^{-\varepsilon} \delta_1 V^2 |S|^{1/2} \sum_\alpha |R_\alpha|^{3/2}
    \end{equation}
    by
    \begin{equation}\label{Exp-2}
        \ll T^\varepsilon S(N,R^{(2)})^{1/2} S(N,S)^{1/2}
    \end{equation}
    for arbitrarily small fixed $\varepsilon$, some $\delta',\delta''>0$ with $\delta' > T^{-\varepsilon} (\delta_1/\delta'')^2$ (see \cite[(4.37)]{bourgain_large_2000}), some set $S$ (which will be non-empty by \cite[(4.47)]{bourgain_large_2000}), and some sets $R_\alpha$ defined in \cite[(4.39)]{bourgain_large_2000}, where the double zeta sums $S(N,W)$ are defined in \eqref{snw}.  Applying Lemma \ref{hb-double}, the latter expression is bounded by
    $$ \ll T^\varepsilon(|R|N^2 + |R|^2 N + |R|^{5/4} T^{1/2} N)^{1/2} (|S| N^2 + |S|^2 N + |S|^{5/4} T^{1/2} N)^{1/2}.$$
    Meanwhile, from \cite[(4.57)]{bourgain_large_2000}, the expression \eqref{Exp-1} is bounded from below by
    $$ \gg T^{-2\varepsilon} (\delta_1^2 V^2 |S| |R| + \delta_1 \delta_2^{1/2} V^2 |S|^{1/2} |R|^{3/2}).$$
    After passing to a subsequence, we can ensure that $|S| = N^{s+o(1)}$ for some $s > 0$.
    Combining these bounds and writing all expressions as powers of $N$, we obtain the claim (after sending $\varepsilon\to 0$).
    \end{proof}

n43941.content:
\begin{corollary}[Bourgain large values theorem, simplified version]\label{borg-lv-simp}\uses{lv-def} \cite[Lemma 4.60]{bourgain_large_2000} Let the notation be as above, but additionally assume $\rho \leq \min(1, 4-2\tau)$.  Then
    $$ \rho \leq \max( \alpha_2 + 2 - 2 \sigma, \alpha_1+\alpha_2/2 + 2-2\sigma, -\alpha_2 + 2\tau+4-8\sigma, -2\alpha_1 + \tau + 12 - 16 \sigma, 4\alpha_1 + 2+\max(1,2\tau-2)-4\sigma).$$
    \end{corollary}

n43944.content:
\begin{proof}\uses{bourgain-lvt}
    Follows from substituting the specified values of $\alpha_1$ and $\alpha_2$ and a routine calculation.
    \end{proof}

n43947.content:
\begin{lemma}[Basic properties of $A$]\label{zero-basic}\uses{zero-def}
\begin{itemize}
\item[(i)] $\sigma \mapsto (1-\sigma) \mathrm{A}(\sigma)$ is non-increasing and left-continuous, with $\mathrm{A}(1/2)=2$.
\item[(ii)] If the Riemann hypothesis holds, then $\mathrm{A}(\sigma)=-\infty$ for all $1/2 < \sigma \leq 1$.
\end{itemize}
\end{lemma}

n43951.content:
\begin{lemma}[Zero density from large values]\label{zero-from-large}\uses{zero-def,lv-def, lvz-def}  Let $1/2 < \sigma < 1$.  Then
$$ \mathrm{A}(\sigma)(1-\sigma) \leq \max( \sup_{\tau \geq 2} \mathrm{LV}_\zeta(\sigma,\tau)/\tau, \limsup_{\tau \to \infty} \mathrm{LV}(\sigma,\tau)/\tau ).$$
\end{lemma}

n43953.content:
\begin{lemma}[Large values from zero density]\label{zero-dens_implies_large}\cite[Theorem 1.2]{matomaki_teravainen_2024}\uses{zero-def, lvz-def} If $\tau > 0$ and $1/2 \leq \sigma \leq 1$ are fixed, then
    $$ \mathrm{LV}_\zeta(\sigma,\tau)/\tau \leq \max\left( \frac{1}{2}, \sup_{\sigma \leq \sigma' \leq 1} \mathrm{A}(\sigma')(1-\sigma') + \frac{\sigma'-\sigma}{2} \right).$$
\end{lemma}

n43959.content:
\begin{corollary}\label{zero-large-cor2}\uses{zero-def, lvz-def, lv-def, zero-large-cor} Let $1/2 < \sigma < 1$ and $\tau_0 > 0$.  Suppose that one has the bounds
\begin{equation}\label{lvo}
\mathrm{LV}(\sigma,\tau) \leq (3-3\sigma) \frac{\tau}{\tau_0}
\end{equation}
for $2\tau_0/3 \leq \tau \leq \tau_0$, and
\begin{equation}\label{lvoz}
 \mathrm{LV}_\zeta(\sigma,\tau) \leq (3-3\sigma) \frac{\tau}{\tau_0}
\end{equation}
for $2 \leq \tau < 4\tau_0/3$.  Then $\mathrm{A}(\sigma) \leq \frac{3}{\tau_0}$.
\end{corollary}

n43960.content:
\begin{corollary}\label{zero-large-cor3}\uses{zero-def, lv-def} Let $1/2 < \sigma < 1$ and $\tau_0 > 0$. Suppose that one has the bound \eqref{lvoz}
   for $2 \leq \tau < 4\tau_0/3$, and the Montgomery conjecture $\mathrm{LV}(\sigma,\tau) \leq 2-2\sigma$ whenever $0 \leq \tau \leq \tau_0+\sigma-1$.  Then $\mathrm{A}(\sigma) \leq \frac{3}{\tau_0}$.
\end{corollary}

n43966.content:
\begin{theorem}[Ingham's first bound]\label{thm:ingham-first}\uses{zeta-grow-def, zero-def} \cite{ingham_difference_1937} (See also \cite{titchmarsh_theory_1986}) For any $1/2 < \sigma < 1$, we have
    $$ \mathrm{A}(\sigma) \leq 2 + 4 \mu(1/2).$$
\end{theorem}

n43969.content:
\begin{proof}\uses{zero-large-cor3, l2-mvt}
We apply Corollary \ref{zero-large-cor3} with $\tau_0 := 2-\sigma$.  Here we have $4\tau_0/3 < 2$ since $\sigma>1/2$, so the claim \eqref{lvoz} is automatic; and the Montgomery conjecture hypothesis follows from Theorem \ref{l2-mvt}.
\end{proof}

n43971.content:
\begin{proof}\uses{zero-large-cor3, huxley-lv, lvz-mu} We apply Corollary \ref{zero-large-cor3} with $\tau_0 := 3\sigma-1$.  The Montgomery conjecture hypothesis follows from Theorem \ref{huxley-lv}. So it remains to show that \eqref{lvoz} holds for $2 \leq \tau < 4\tau_0/3$.  For $\sigma \leq 5/6$ we have $4\tau_0/3 \leq 2$, so the claim is vacuously true in this case.  For $\sigma > 5/6$ we use Corollary \ref{lvz-mu} and the bound $\mu(1/2) \leq 1/6$ from Table \ref{mu-table} to conclude that
$\mathrm{LV}_\zeta(\sigma,\tau) = -\infty$ whenever $\sigma > 1/2 + \tau/6$, but this is precisely $\tau < 6\sigma - 3$.  Since $6\sigma-3 > 4\tau_0/3$ when $\sigma > 5/6$, we obtain the claim.
\end{proof}

n43973.content:
\begin{proof}\uses{thm:ingham_zero_density2, huxley-lv,zero-large-cor2, guth-maynard-lvt, l2-mvt} We may assume that $7/10 < \sigma < 8/10$, since the bound follows from the Ingham and Huxley bounds otherwise.  We apply Corollary \ref{zero-large-cor2} with $\tau_0 := \frac{3+5\sigma}{5}$.  We have $4\tau_0/3 < 2$, so the claim \eqref{lvoz} is vacuous and we only need to establish \eqref{lvo}.  We split into the subranges $13/5-2\sigma \leq \tau < \tau_0$ and $2\tau_0/3 \leq \tau \leq 13/5-2\sigma$. In the former range we use Theorem \ref{guth-maynard-lvt} (and \eqref{obvious}), and reduce to showing that
$$ 18/5 - 4 \sigma \leq (3-3\sigma) \frac{\tau}{\tau_0},$$
and
$$ \tau + 12/5 - 4\sigma \leq (3-3\sigma) \frac{\tau}{\tau_0}$$
for $13/5-2\sigma \leq \tau < \tau_0$.  The first inequality follows from
\begin{equation}\label{18-5}
 18/5 - 4 \sigma \leq (3-3\sigma) \frac{13/5-2\sigma}{\tau_0}
\end{equation}
which one can numerically check holds in the range $7/10 < \sigma < 8/10$.  Finally, the third inequality is obeyed with equality when $\tau=\tau_0$ and the right-hand side has a larger slope in $\tau$ than the left (since $\tau_0 \geq 3-3\sigma$), so the claim follows as well.

In the remaining region $2\tau_0/3 \leq \tau \leq 13/5-2\sigma$, we use Theorem \ref{l2-mvt} and \eqref{obvious} to reduce to showing that
$$ \tau + 1 - 2\sigma \leq (3-3\sigma) \frac{\tau}{\tau_0}$$
in this range.  This follows again from \eqref{18-5} which guarantees the inequality at the right endpoint $\tau = 13/5-2\sigma$.
\end{proof}

n43981.content:
\begin{proof}\uses{zero-large-cor3, 3-40, hb-opt, lvz-exp}  We apply Corollary \ref{zero-large-cor3} with $\tau_0 := 10\sigma-7$.  The claim \eqref{lvo} again follows from
    Theorem \ref{hb-opt} and \eqref{obvious} as in the proof of Theorem \ref{hb-density}.  Meanwhile, from Lemma \ref{3-40} and Corollary \ref{lvz-exp} we have $\mathrm{LV}_\zeta(\sigma,\tau) = -\infty$ whenever $\sigma > \frac{3}{40} \tau + \frac{7}{10}$, or equivalently $\tau < \frac{4}{3} (10\sigma-7)$, which then immediately gives \eqref{lvoz}.
\end{proof}

n43983.content:
\begin{proof}  The arguments below are a translation of the original arguments of Bourgain \cite{bourgain_large_2000} to our notational framework.

In view of Theorem \ref{jutila-density} (or Theorem \ref{hb-density}), we may assume that $25/32 < \sigma < 11/14$.  Set $\rho := \mathrm{LV}(\sigma,\tau)$. As in the proof of Theorem \ref{jutila-density}, it suffices to show that
\begin{equation}\label{rot}
    \rho \leq (2-2\sigma) \tau
\end{equation}
for all $1 \leq \tau \leq 3/2$.

From the $k=3$ case of Theorem \ref{jutila-lvt} we have
\begin{equation}\label{rhomax}
    \rho \leq \max \bigg(2-2\sigma, \tau + \frac{10-16\sigma}{3}, \tau + 18-24\sigma \bigg)
\end{equation}
which in the $\sigma < 11/14$ regime simplifies to
\begin{equation}\label{r0-start}
\rho \leq \max(2-2\sigma, \tau + 18-24\sigma)
\end{equation}
and this already suffices unless
\begin{equation}\label{tau-check}
     \tau \geq \frac{24\sigma-18}{2\sigma-1}.
\end{equation}
In the regime $\sigma > 25/32$ and $\tau \leq 3/2$, the bound \eqref{r0-start} certainly implies
$$ \rho \leq \min(1, 4-2\tau)$$
and also
$$ \max(1,2\tau-2) = 1$$
so we may invoke Corollary \ref{borg-lv-simp} to conclude that
\begin{equation}\label{40}
     \rho \leq \max( \alpha_2 + 2 - 2 \sigma, \alpha_1+\alpha_2/2 + 2-2\sigma, -\alpha_2 + 2\tau+4-8\sigma, -2\alpha_1 + \tau + 12 - 16 \sigma, 4\alpha_1 + 3-4\sigma)
\end{equation}
for any $\alpha_1, \alpha_2 \geq 0$.

We now divide into cases.  First suppose that $\tau \leq \frac{4(1+\sigma)}{5}$.  In this case we set $\alpha_1 := \frac{\tau}{3} - \frac{2}{3} (7\sigma-5)$ (which can be checked to be nonnegative using \eqref{tau-check} and $\sigma \geq 25/32$) and $\alpha_2=0$, and one can check that \eqref{40} implies \eqref{rot} in this case (with some room to spare).

Now suppose that $\tau > \frac{4(1+\sigma)}{5}$.  In this case we choose $\alpha_1 = \frac{\tau}{8} - \frac{9\sigma-7}{2}$ and $\alpha_2 = \frac{5\tau}{4} - (1+\sigma)$, which can be checked to be nonnegative using the hypotheses on $\sigma,\tau$.  In this case
one can again check that \eqref{40} implies \eqref{rot}.
\end{proof}

n43990.content:
\begin{proof}\uses{bourgain-zd, H-pairs, new-exp-pair}
Let $\mathcal{S}(\sigma)$ denote the closure of the region
\begin{align*}
\Bigg\{(k, \ell) : 0 < k < \frac{1}{5}, \frac{3}{5} < \ell < 1, 15\ell + 20k > 13, \frac{\ell + 1}{2(k + 1)} < \sigma, \\
k < \frac{11}{85} \text{ or } \left(k > \frac{11}{85} \text{ and } \frac{144k - 11\ell - 11}{170k - 22} < \sigma\right)\Bigg\}
\end{align*}
One may verify that $\mathcal{S}(\sigma)$ is a convex polygon for all $3/4 < \sigma < 1$, and thus so is $\mathcal{S}(\sigma) \cap H$, where $H$ is the convex hull of exponent pairs. Thus
\[
\min_{(k, \ell) \in \mathcal{S}(\sigma) \cap H}\frac{4k}{2(1 + k)\sigma - 1 - \ell}
\]
is a convex optimisation problem for each $3/4 < \sigma < 1$.
We take the following choices of $(k, \ell)$ (found with the aid of computer assistance).
\[
\left(\frac{11}{85} - \varepsilon, \frac{59}{85} + 2\varepsilon\right),
\left(\frac{391}{4595} + \varepsilon, \frac{3461}{4595}\right),
\left(\frac{2779}{38033} + \varepsilon, \frac{58699}{76066}\right),
\left(\frac{89}{1282} + \varepsilon, \frac{997}{1282}\right),
\]
\[
\left(\frac{652397}{9713986} + \varepsilon, \frac{7599781}{9713986}\right),
\left(\frac{2371}{43205} + \varepsilon, \frac{280013}{345640}\right),
\left(\frac{9}{217} + \varepsilon, \frac{1461}{1736}\right), \left(\frac{10769}{351096} + \varepsilon, \frac{609317}{702192}\right).
\]
Of these exponent pairs:
\begin{itemize}
    \item $(\frac{11}{85}, \frac{59}{85})$ is the intersection of the lines $k = 1/5$ and $15\ell + 20k = 13$;
    \item $(\frac{391}{4595}, \frac{3461}{4595})$ is an intersection of the line $15\ell + 20k = 13$ and the boundary of $H$;
    \item all other exponent pairs are vertices of $H$.
\end{itemize}
The desired result follows from taking a minimum over the implied bounds. Sharper bounds are possible close to $\sigma = 1$ by choosing other exponent pairs, however it turns out such results are superseded by other zero density estimates.
\end{proof}

n43993.content:
\begin{lemma}[Zero density from $\mu$ bound]\label{zero_from_mu}\cite[Theorem 12.3]{montgomery_topics_1971}\uses{zeta-grow-def, zero-def} If $1/2 \leq \alpha \leq 1$ and $\frac{\alpha+1}{2} \leq \sigma \leq 1$, then
$$ \mathrm{A}(\sigma) \leq \mu(\alpha) \frac{2(3\sigma-1-2\alpha)}{(2\sigma-1-\alpha)(\sigma-\alpha)}.$$
\end{lemma}

n43998.content:
\begin{lemma}[General zero density estimate]\label{gzd}\cite[(11.76), (11.77)]{ivic}\uses{exp-pair-def, zero-def} If $(k,\ell)$ is an exponent pair, and $m \geq 2$ an integer, then
$$ \mathrm{A}(\sigma) \leq \frac{3m}{(3m-2)\sigma + 2 - m}$$
whenever
\begin{align*}
\sigma &\geq \min\biggl( \frac{6m^2-5m+2}{8m^2-7m+2},\\
&\qquad \max\left( \frac{9m^2-4m+2}{12m^2-6m+2}, \frac{3m^2(1+2k+2\ell)-(4k+2\ell)m + 2k+2\ell}{4m^2(1+2k+2\ell)-(6k+4\ell)m + 2k+2\ell} \right) \biggr).
\end{align*}
\end{lemma}

n44000.content:
\begin{corollary}[1980-1984 Ivic zero density bound]\label{further_ivic_zero}\uses{zero-def}\cite{ivic_exponent_pairs}, \cite[Theorem 11.4]{ivic} One can bound $\mathrm{A}(\sigma$) by
\begin{align*}
 \frac{3}{2\sigma} &\hbox{ for } \frac{3831}{4791} \leq \sigma \leq 1;\\
 \frac{9}{7\sigma-1} &\hbox{ for } \frac{41}{53} \leq \sigma \leq 1; \\
 \frac{6}{5\sigma-1} &\hbox{ for } \frac{13}{17} \leq \sigma \leq 1; \\
 \frac{15}{13\sigma-3} &\hbox{ for } \frac{127}{167} \leq \sigma \leq 1; \\
 \frac{9}{8\sigma-2} &\hbox{ for } \frac{47}{62} \leq \sigma \leq 1;
\end{align*}
\end{corollary}

n44003.content:
\begin{lemma}[Preliminary large values theorem]\label{a-ivt}\uses{lv-def}  If $1/2 \leq \sigma \leq 1$ and $\tau < 8\sigma-5$, then
    $$ \mathrm{LV}(\sigma,\tau) \leq \max( 2-2\sigma, 6\tau/5 + (20-32\sigma)/5 ).$$
\end{lemma}

n44007.content:
\begin{theorem}[Pintz zero density theorem]\label{pintz-density}\uses{zero-def}\cite[Theorem 1]{pintz_density_2023}  If $k \geq 4$, $\ell \geq 3$ are integers and $\sigma = 1-\eta$ is such that
\begin{equation}\label{eta-b}
    \frac{1}{k(k+1)} \leq \eta < \frac{1}{k(k-1)}
\end{equation}
and
\begin{equation}\label{eta-l}
 \frac{1}{2\ell(\ell+1)} \leq \eta < \frac{1}{2\ell(\ell-1)}
\end{equation}
then
$$ \mathrm{A}(\sigma) \leq \max\left( \frac{3}{\ell(1-2(\ell-1)\eta)}, \frac{4}{k(1-(k-1)\eta)}\right).$$
\end{theorem}

