\begin{theorem}[\cite{chourasiya_explicit_2024}]For every $T\ge 3$ and $\sigma\ge 3/5$, one has
    \begin{equation*}
N(\sigma, T) \leq 0.7756 T^{4 \sigma(1-\sigma)} \log ^{5-2 \sigma} T.
\end{equation*}
\end{theorem}

