n44020.content:
\begin{lemma}[Basic properties of $\mathrm{A}^*$]\label{zeroe-basic}\uses{zeroe-def}
\begin{itemize}
\item[(i)] We have the trivial bounds
$$ 2\mathrm{A}(\sigma), 4\mathrm{A}(\sigma)-\frac{1}{1-\sigma} \leq \mathrm{A}^*(\sigma) \leq 3 \mathrm{A}(\sigma)$$
for any $1/2 \leq \sigma \leq 1$.
\item[(ii)] $\sigma \mapsto (1-\sigma) \mathrm{A}^*(\sigma)$ is non-increasing, with $\mathrm{A}^*(1/2)=6$ and $\mathrm{A}^*(1)=-\infty$.
\item[(iii)] If the Riemann hypothesis holds, then $\mathrm{A}^*(\sigma)=-\infty$ for all $1/2 < \sigma \leq 1$.
\end{itemize}
\end{lemma}

n44022.content:
\begin{lemma}[Zero density energy from large values energy]\label{zeroe-from-large}\uses{lvze-def}  Let $1/2 < \sigma < 1$.  Then
$$ \mathrm{A}^*(\sigma)(1-\sigma) \leq \max\left( \sup_{\tau \geq 1} \mathrm{LV}^*_\zeta(\sigma,\tau)/\tau, \limsup_{\tau \to \infty} \mathrm{LV}^*(\sigma,\tau)/\tau \right).$$
\end{lemma}

n44024.content:
\begin{corollary}\label{zeroe-large-cor-0}\uses{zeroe-def, lvze-def} Let $1/2 < \sigma < 1$ and $\tau_0 > 0$ be fixed.  Then
$$ \mathrm{A}^*(\sigma)(1-\sigma) \leq \max \left(\sup_{2 \leq \tau < \tau_0} \mathrm{LV}^*_\zeta(\sigma,\tau)/\tau, \sup_{\tau_0 \leq \tau \leq 2\tau_0} \mathrm{LV}^*(\sigma,\tau)/\tau\right)$$
\end{corollary}

n44028.content:
\begin{theorem}[Heath-Brown's additive energy bound]\label{hb-energy-bound}\cite[Theorem 2]{heathbrown_zero_1979}\uses{zeroe-def}  Let $1/2 \leq \sigma \leq 1$ be fixed.  Then one can bound $A^*(\sigma)$ by
    \begin{align*}
        \frac{10-11\sigma}{(2-\sigma)(1-\sigma)} & \hbox{ for } 1/2 \leq \sigma \leq 2/3;\\
        \frac{18-19\sigma}{(4-2\sigma)(1-\sigma)} & \hbox{ for } 2/3 \leq \sigma \leq 3/4;\\
        \frac{12}{4\sigma-1} & \hbox{ for } 3/4 \leq \sigma \leq 1.
    \end{align*}
\end{theorem}

