n44047.content:
\begin{lemma}[Basic properties of zero free regions]\label{zero-free-basic-lem}
The following properties hold:
\begin{enumerate}
    \item[(i)] (Symmetry about the real axis) If $\zeta(\sigma + it) \ne 0$ then $\zeta(\sigma - it) \ne 0$.
    \item[(ii)] (Symmetry about the critical line $\Re s = 1/2$) For $0 \le \sigma \le 1$, if $\zeta(\sigma + it) \ne 0$ then $\zeta(1 - \sigma + it) \ne 0$.
    \item[(iii)] (Non vanishing for $\Re s > 1$) If $\Re s > 1$ then $\zeta(s) \ne 0$.
\end{enumerate}
\end{lemma}

n44049.content:
\begin{conjecture}[Riemann hypothesis]\label{rh}
If $\rho$ is a non-trivial zero of the Riemann zeta function, then $\Re \rho = 1/2$.
\end{conjecture}

n44050.content:
\begin{theorem}[Non-vanishing on the 1-line]
One has $\zeta(1 + it) \ne 0$ for any real $t$.
\end{theorem}

n44055.content:
\begin{proof}
Thanks to the convexity bound $\mu(\sigma) \le (1-\sigma)/2$, one may take $g(t) = 1/2$, $f(t) = t^{1/4 + o(1)}$ in \Cref{mu_to_zero_free}. The result follows.
\end{proof}

n44056.content:
\begin{theorem}[Littlewood zero free region]\label{zfr-littlewood}
One has $\zeta(\sigma + it) \ne 0$ if
\[
\sigma \ge 1 - \frac{A \log\log t}{\log t}
\]
for an absolute constant $A > 0$ and $t$ sufficiently large.
\end{theorem}

n44058.content:
\begin{theorem}[Chudakov zero free region]\label{zfr-chudakov}
One has $\zeta(\sigma + it) \ne 0$ if
\[
\sigma \ge 1 - \frac{1}{(\log t)^{3/4 + o(1)}}
\]
for $t$ sufficiently large.
\end{theorem}

n44059.content:
\begin{theorem}[Korobov-Vinogradov zero free region]\label{zfr-vk}
One has $\zeta(\sigma + it) \ne 0$ if
\[
\sigma \ge 1 - \frac{A}{(\log t)^{2/3}(\log\log t)^{1/3}}
\]
for an absolute constant $A > 0$ and $t$ sufficiently large.
\end{theorem}

n44063.content:
\begin{theorem}[Prime number theorem, alternative formulations]
As $x \to \infty$, one has $\psi(x) \sim x$ and $\theta(x) \sim x$.
\end{theorem}

n44064.content:
\begin{theorem}[Korobov--Vinogradov estimate]
There exists a positive constant $A$, such that
\begin{align*}
\psi(x) - x, \; \theta(x) - x, \; \pi(x) - \operatorname{li}(x) \ll x\exp\left(-A\frac{(\log x)^{3/5}}{(\log\log x)^{1/5}}\right).
\end{align*}
\end{theorem}

n44076.content:
\begin{proposition}[Zero density theorems and prime gaps]\label{prime-gap}  Let
\begin{equation}\label{A-def}
    \|\mathrm{A}\|_\infty := \sup_{1/2 \leq \sigma \leq 1} A(\sigma).
\end{equation}
Then
    $$ \theta_{\mathrm{PNT}}\leq 1 - \frac{1}{\|\mathrm{A}\|_\infty}$$
    and
    $$ \theta_{\mathrm{PNT-AA}}\leq 1 - \frac{2}{\|\mathrm{A}\|_\infty}.$$
\end{proposition}

n44086.content:
\begin{corollary}\
    \begin{itemize}
    \item[(i)] Assuming the Riemann hypothesis, $\theta_{\mathrm{gap},2}= 1$. (Selberg, 1943 \cite{selberg_1943})
    \item[(ii)] Assuming the Lindelof hypothesis, $\theta_{\mathrm{gap},2}\leq 7/6$. (Heath-Brown, 1979 \cite{heath_brown_consecutive_II})
    \item[(iii)] Unconditionally, $\theta_{\mathrm{gap},2}\leq 23/18$. (Heath-Brown, 1979 \cite{heath_brown_consecutive_III}).
\end{itemize}
\end{corollary}

n44097.content:
\begin{theorem}[Ford--Green--Konyagin--Maynard--Tao (2017) \cite{ford_long_2017}]
For unbounded $X$, one has
\[
G(X) \gg \frac{\log X \log \log X \log\log\log \log X}{\log \log \log X}
\]
\end{theorem}

n44103.content:
\begin{lemma}[Lower bound on $\alpha_k$ and $\beta_k$]\label{divisor-lower}\uses{divisor-def}
For all $k \geq 1$, one has
\[
\alpha_k \geq \beta_k \geq \frac{1}{2} - \frac{1}{2k}.
\]
\end{lemma}

n44104.content:
\end{lemma}
\begin{proof}The first inequality follows from inserting the bound $\Delta_k(x) \ll x^{\alpha_k + o(1)}$ into the definition of $\beta_k$. The second inequality is due to Titchmarsh \cite{titchmarsh_divisor_1938}. Note also that the weaker inequality $\alpha_k \ge 1/2 - 1/(2k)$ was first proved by Hardy \cite{hardy_divisor_1916}.
\end{proof}

n44112.content:
