n44160.content:
\begin{definition}
    Define the Schnirelmann density of $A\subset \mathbf{N}$ as
    $$\sigma A=\inf_{n\ge1}\frac{\#(A\cap J_n)}{n}$$
\end{definition}

n44161.content:
\begin{definition}
    Define the lower asymptotic density of $A\subset \mathbf{N}$ as
    $$\delta A=\liminf_{n\to\infty}\frac{\#(A\cap J_n)}{n}$$
\end{definition}

n44162.content:
\begin{theorem}[Schnirelmann \cite{Schnirelmann1933}]
    Suppose $\sigma A>0$. Then $A$ is an additive basis for $\mathbf{N}$. \label{addbasisthm}
\end{theorem}

n44163.content:
\begin{theorem}[Schnirelmann \cite{Schnirelmann1933}]
    Let $\mathbb P$ denote the set of primes. Then, $\delta(\mathbb P+\mathbb P)>0$. Therefore, $\mathbb P$ is an additive basis for $\mathbf{N}$. The order of $\mathbb P$ is denoted $C$ and called Schnirelmann's constant.
\end{theorem}

n44164.content:
\begin{theorem}[Romanoff \cite{ASNSP_1995_4_22_4_645_0}]
    Let $\mathfrak S_a=\{p+a^k:p\in\mathbb P, k\in\mathbf{N}\}$. Then, $\sigma\mathfrak S_a>0$ for all $a\in\mathbf{N}$. Thus, each integer $n$ may be written as the sum of at most $C_a$ primes and $C_a$ powers of $a$, where $C_a$ is a constant depending only on $a$.
\end{theorem}

n44165.content:
\begin{definition}
    $B\subset \mathbf{N}$ is called an essential component if $\sigma(A+B)>\sigma(A)$ for any $A\subset\mathbf{N}$ with $0<\sigma A<1$.
\end{definition}

n44166.content:
\begin{definition}
For fixed integer $k \ge 2$, define $\theta^{\operatorname{Gauss}}_{k}$ as the least (fixed) exponent for which
\[
S_k(R) - \operatorname{Vol}(B_k(R)) \ll R^{\theta^{\operatorname{Gauss}}_{k} + o(1)}.
\]
\end{definition}
